import itertools

n = 24
fixed_seq = {9: -1, 14: 1, 15: -1, 22: -1}
fixed_c = {3: 0, 9: -2, 14: -1, 19: 0}

def solve():
    # Find free indices
    free_indices = [i for i in range(n) if i not in fixed_seq]

    # Iterate over all combinations
    for p in itertools.product([-1, 1], repeat=len(free_indices)):
        seq = [0] * n
        for i, val in fixed_seq.items():
            seq[i] = val
        for i, val in zip(free_indices, p):
            seq[i] = val

        # Check fixed C_k
        valid = True
        for k, expected_c in fixed_c.items():
            c_k = sum(seq[i] * seq[i+k] for i in range(n-k))
            if c_k != expected_c:
                valid = False
                break
        if not valid:
            continue

        # Check sum of C_k^2
        sum_c2 = 0
        for k in range(1, n):
            c_k = sum(seq[i] * seq[i+k] for i in range(n-k))
            sum_c2 += c_k**2
            if sum_c2 > 62:
                valid = False
                break

        if valid:
            print("Found:", seq)
            return seq

    print("UNSATISFIABLE")

solve()

